if (flow.get('trumaTemperatureReadBusy')) return null;
flow.set('trumaTemperatureReadBusy', true);
return msg;

// Raw Truma temperatures are tenths of a degree Celsius.
// Feed fresh get-node results here, never the merged discovery cache.
const now = Date.now();
const staleAfterMs = 5 * 60 * 1000;
const names = ['AirHeating', 'WaterHeating'];
let state = context.get('sensors') || [{ last: 0, online: false }, { last: 0, online: false }];
const output = [null, null];
if (msg.kind !== 'tick') flow.set('trumaTemperatureReadBusy', false);
for (let i = 0; i < names.length; i++) {
  if (msg.kind !== 'tick' && !msg.error) {
    const parameter = msg.payload?.topics?.[names[i]]?.parameters?.Temp;
    const raw = parameter?.value;
    const valid = parameter?.available !== 0 && parameter?.available !== false &&
      typeof raw === 'number' && Number.isFinite(raw) && raw >= -500 && raw <= 1500;
    if (valid) {
      output[i] = [{ payload: { '/Temperature': raw / 10, '/Status': 0 } }, { connected: true }];
      state[i] = { last: now, online: true };
      continue;
    }
    state[i].last = 0;
  }
  if (msg.error || !state[i].last || now - state[i].last >= staleAfterMs) {
    output[i] = { connected: false };
    state[i] = { last: 0, online: false };
  }
}
context.set('sensors', state);
return output;
